param([string]$InstallRoot='C:\Program Files\{{SERVICE}}',[string]$DataRoot='C:\ProgramData\{{SERVICE}}',[string]$TaskName='{{SERVICE}} Service')
$ErrorActionPreference='Stop';if(!(Test-Path "$DataRoot\config\service.json")){throw 'Run Configure-{{SERVICE}}.ps1 first'};$launcher="$InstallRoot\tools\Start-{{SERVICE}}.ps1";$args="-NoProfile -ExecutionPolicy RemoteSigned -File `"$launcher`" -InstallRoot `"$InstallRoot`" -DataRoot `"$DataRoot`""
$action=New-ScheduledTaskAction -Execute 'powershell.exe' -Argument $args;$trigger=New-ScheduledTaskTrigger -AtStartup;$principal=New-ScheduledTaskPrincipal -UserId 'NT AUTHORITY\LOCAL SERVICE' -LogonType ServiceAccount -RunLevel Highest;$settings=New-ScheduledTaskSettingsSet -RestartCount 3 -RestartInterval (New-TimeSpan -Minutes 1) -ExecutionTimeLimit ([TimeSpan]::Zero) -MultipleInstances IgnoreNew
Register-ScheduledTask -TaskName $TaskName -Action $action -Trigger $trigger -Principal $principal -Settings $settings -Force|Out-Null;Start-ScheduledTask $TaskName;[ordered]@{registered=$true;task=$TaskName;identity='NT AUTHORITY\LOCAL SERVICE'}|ConvertTo-Json
